  String? get secret => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 6);
  int get pin => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 8, 0);
  bool get flag => const fb.BoolReader().vTableGet(_bc, _bcOffset, 10, false);
  Level get level => Level.fromValue(const fb.Int8Reader().vTableGet(_bc, _bcOffset, 12, 1));
  int get count => const fb.Int16Reader().vTableGet(_bc, _bcOffset, 14, 0);
  int get total => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 16, 0);
  double get ratio => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 18, 0.0);
