class NodeObjectBuilder extends fb.ObjectBuilder {
  final String? _name;
  final String? _secret;
  final int? _pin;
  final bool? _flag;
  final Level? _level;
  final int? _count;
  final int? _total;
  final double? _ratio;
  final Vec3ObjectBuilder? _position;
  final List<int>? _bytes;
  final List<double>? _readings;
  final List<Vec3ObjectBuilder>? _points;
  final List<String>? _tags;
  final NodeObjectBuilder? _child;
  final List<NodeObjectBuilder>? _children;
  final PayloadTypeId? _payloadType;
  final dynamic _payload;
  final int? _plain;

  NodeObjectBuilder({
    String? name,
    String? secret,
    int? pin,
    bool? flag,
    Level? level,
    int? count,
    int? total,
    double? ratio,
    Vec3ObjectBuilder? position,
    List<int>? bytes,
    List<double>? readings,
    List<Vec3ObjectBuilder>? points,
    List<String>? tags,
    NodeObjectBuilder? child,
    List<NodeObjectBuilder>? children,
    PayloadTypeId? payloadType,
    dynamic payload,
    int? plain,
  })
      : _name = name,
        _secret = secret,
        _pin = pin,
        _flag = flag,
        _level = level,
        _count = count,
        _total = total,
        _ratio = ratio,
        _position = position,
        _bytes = bytes,
        _readings = readings,
        _points = points,
        _tags = tags,
        _child = child,
        _children = children,
        _payloadType = payloadType,
        _payload = payload,
        _plain = plain;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? nameOffset = _name == null ? null
        : fbBuilder.writeString(_name!);
    final int? secretOffset = _secret == null ? null
        : fbBuilder.writeString(_secret!);
    final int? bytesOffset = _bytes == null ? null
        : fbBuilder.writeListUint8(_bytes!);
    final int? readingsOffset = _readings == null ? null
        : fbBuilder.writeListFloat32(_readings!);
    final int? pointsOffset = _points == null ? null
        : fbBuilder.writeListOfStructs(_points!);
    final int? tagsOffset = _tags == null ? null
        : fbBuilder.writeList(_tags!.map(fbBuilder.writeString).toList());
    final int? childOffset = _child?.getOrCreateOffset(fbBuilder);
    final int? childrenOffset = _children == null ? null
        : fbBuilder.writeList(_children!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? payloadOffset = _payload?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(18);
    fbBuilder.addOffset(0, nameOffset);
    fbBuilder.addOffset(1, secretOffset);
    fbBuilder.addUint32(2, _pin);
    fbBuilder.addBool(3, _flag);
    fbBuilder.addInt8(4, _level?.value);
    fbBuilder.addInt16(5, _count);
    fbBuilder.addInt64(6, _total);
    fbBuilder.addFloat64(7, _ratio);
    if (_position != null) {
      fbBuilder.addStruct(8, _position!.finish(fbBuilder));
    }
    fbBuilder.addOffset(9, bytesOffset);
    fbBuilder.addOffset(10, readingsOffset);
    fbBuilder.addOffset(11, pointsOffset);
    fbBuilder.addOffset(12, tagsOffset);
    fbBuilder.addOffset(13, childOffset);
    fbBuilder.addOffset(14, childrenOffset);
    fbBuilder.addUint8(15, _payloadType?.value);
    fbBuilder.addOffset(16, payloadOffset);
    fbBuilder.addUint32(17, _plain);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
